    );

//palette size
float palette_size = 8.0;

vec3 getPalette(int idx);
void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 uv = fragCoord.xy / iResolution.xy;
    vec3 sampled_color = texture(iChannel0, uv).rgb;
    vec3 color =sampled_color;

    int u_x = int(mod(fragCoord.x, 4.0));
    int u_y = int(mod(fragCoord.y, 4.0));

    float dither_value = bayer4x4[u_x][u_y] / palette_size;




    color = findNearestColor(color);

    color += (dither_value);


    fragColor = vec4(color, 1.0);
}

vec3 findNearestColor(vec3 color)
{
    float minDist = 10000.0f;

    vec3 out_color;

    for (int i = 0; i < int(palette_size); i++)
    {
        vec3 pal_col = getPalette(i);
        float dist = (distance(pal_col, color));
        if (dist < minDist)
        {
            minDist = dist;
            out_color = pal_col;
        }
    }

    return out_color;
}
vec3 getPalette(int idx)
{
    float uv_x = ((float(idx) + 0.5) / palette_size);

    return palette[idx];
}
